/// Canonical_Combining_Class.
#[inline]
pub(crate) fn ccc(cp: u32) -> u32 {
    ccc_inside(cp).unwrap_or(0)
}

#[inline]
fn ccc_inside(cp: u32) -> Option<u32> {
    let c = cp.checked_sub(0x300)?;
    if c > 0x1e64a {
        return None;
    }
    let i1 = get8(&CCC_S1, c >> 7)?;
    let i2 = get8(&CCC_S2, (i1 << 4) | ((c >> 3) & 0xf))?;
    get8(&CCC_S3, (i2 << 3) | (c & 0x7))
}

