/// The canonical decomposition: 0 for none, `1..=DM1.len()` for
/// `DM1[n - 1]`, then `DM2[n - 1 - DM1.len()]`.
#[inline]
pub(crate) fn dm(cp: u32) -> u32 {
    dm_inside(cp).unwrap_or(0)
}

#[inline]
fn dm_inside(cp: u32) -> Option<u32> {
    let c = cp.checked_sub(0xc0)?;
    if c > 0x2f95d {
        return None;
    }
    let i1 = get8(&DM_S1, c >> 9)?;
    let i2 = get8(&DM_S2, (i1 << 5) | ((c >> 4) & 0x1f))?;
    get16(&DM_S3, (i2 << 4) | (c & 0xf))
}

