/// Vertical_Orientation: 0 U, 1 R, 2 Tu, 3 Tr.
#[inline]
pub(crate) fn vo(cp: u32) -> u32 {
    vo_inside(cp).unwrap_or(1)
}

#[inline]
fn vo_inside(cp: u32) -> Option<u32> {
    let c = cp.checked_sub(0xa7)?;
    if c > 0x10ff56 {
        return None;
    }
    let i1 = get8(&VO_S1, c >> 10)?;
    let i2 = get8(&VO_S2, (i1 << 5) | ((c >> 5) & 0x1f))?;
    get4(&VO_S3, (i2 << 5) | (c & 0x1f))
}

